package com.healthcare.fog.model;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.index.CompoundIndex;
import org.springframework.data.mongodb.core.index.CompoundIndexes;
import org.springframework.data.mongodb.core.index.Indexed;
import org.springframework.data.mongodb.core.mapping.Document;

import java.time.Instant;

/**
 * MongoDB document representing clinical medical alerts generated by the Fog Computing Layer
 * upon abnormal vital threshold detection.
 *
 * NOTE: Thresholds and alert criteria are configured exclusively for academic demonstration
 * and edge computing evaluation, NOT for clinical diagnostic use.
 */
@Document(collection = "emergency_alerts")
@CompoundIndexes({
    @CompoundIndex(name = "patient_alert_time_idx", def = "{'patientId': 1, 'timestamp': -1}"),
    @CompoundIndex(name = "status_alert_time_idx", def = "{'status': 1, 'timestamp': -1}")
})
public class EmergencyAlert {

    @Id
    private String id;

    @Indexed(sparse = true)
    private String alertId;

    // Patient Details
    @Indexed
    private String patientId;
    private String patientName;
    private Integer patientAge;
    private String patientGender;

    // Fog Node & Sensor Metadata
    @Indexed
    private String fogNodeId;
    private String fogNodeName;
    private String sensorDeviceId;

    // Alert Classification & Parameter Details
    private String alertLevel;  // WARNING, CRITICAL
    private String status;      // ACTIVE, ACKNOWLEDGED, RESOLVED
    private String vitalType;   // HEART_RATE, SPO2, TEMPERATURE, SYSTOLIC_BP, DIASTOLIC_BP
    private Double measuredValue;
    private Double thresholdLimit;
    private Double thresholdExceeded;
    private String message;

    private Instant timestamp;
    private boolean forwardedToCloud;

    // Clinician Acknowledgement
    private boolean acknowledged;
    private Instant acknowledgedAt;
    private String acknowledgedBy;
    private String acknowledgementNotes;

    // Clinician Resolution (Mandatory manual resolution for CRITICAL alerts)
    private boolean resolved;
    private Instant resolvedAt;
    private String resolvedBy;
    private String resolutionNotes;

    // Academic Demonstration Notice
    private String demonstrationNotice = "Academic demonstration threshold alert - not for medical diagnostic use";

    public EmergencyAlert() {
        this.timestamp = Instant.now();
        this.status = "ACTIVE";
        this.acknowledged = false;
        this.resolved = false;
        this.forwardedToCloud = true;
    }

    public EmergencyAlert(String alertId, String patientId, String patientName, Integer patientAge,
                          String patientGender, String fogNodeId, String fogNodeName,
                          String sensorDeviceId, String alertLevel, String vitalType,
                          Double measuredValue, Double thresholdLimit, Double thresholdExceeded,
                          String message) {
        this.alertId = alertId;
        this.patientId = patientId;
        this.patientName = patientName;
        this.patientAge = patientAge;
        this.patientGender = patientGender;
        this.fogNodeId = fogNodeId;
        this.fogNodeName = fogNodeName;
        this.sensorDeviceId = sensorDeviceId;
        this.alertLevel = alertLevel;
        this.vitalType = vitalType;
        this.measuredValue = measuredValue;
        this.thresholdLimit = thresholdLimit;
        this.thresholdExceeded = thresholdExceeded;
        this.message = message;
        this.timestamp = Instant.now();
        this.status = "ACTIVE";
        this.acknowledged = false;
        this.resolved = false;
        this.forwardedToCloud = true;
    }

    // Getters and Setters
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getAlertId() {
        return alertId;
    }

    public void setAlertId(String alertId) {
        this.alertId = alertId;
    }

    public String getPatientId() {
        return patientId;
    }

    public void setPatientId(String patientId) {
        this.patientId = patientId;
    }

    public String getPatientName() {
        return patientName;
    }

    public void setPatientName(String patientName) {
        this.patientName = patientName;
    }

    public Integer getPatientAge() {
        return patientAge;
    }

    public void setPatientAge(Integer patientAge) {
        this.patientAge = patientAge;
    }

    public String getPatientGender() {
        return patientGender;
    }

    public void setPatientGender(String patientGender) {
        this.patientGender = patientGender;
    }

    public String getFogNodeId() {
        return fogNodeId;
    }

    public void setFogNodeId(String fogNodeId) {
        this.fogNodeId = fogNodeId;
    }

    public String getFogNodeName() {
        return fogNodeName;
    }

    public void setFogNodeName(String fogNodeName) {
        this.fogNodeName = fogNodeName;
    }

    public String getSensorDeviceId() {
        return sensorDeviceId;
    }

    public void setSensorDeviceId(String sensorDeviceId) {
        this.sensorDeviceId = sensorDeviceId;
    }

    public String getAlertLevel() {
        return alertLevel;
    }

    public void setAlertLevel(String alertLevel) {
        this.alertLevel = alertLevel;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getVitalType() {
        return vitalType;
    }

    public void setVitalType(String vitalType) {
        this.vitalType = vitalType;
    }

    public Double getMeasuredValue() {
        return measuredValue;
    }

    public void setMeasuredValue(Double measuredValue) {
        this.measuredValue = measuredValue;
    }

    public Double getThresholdLimit() {
        return thresholdLimit;
    }

    public void setThresholdLimit(Double thresholdLimit) {
        this.thresholdLimit = thresholdLimit;
    }

    public Double getThresholdExceeded() {
        return thresholdExceeded;
    }

    public void setThresholdExceeded(Double thresholdExceeded) {
        this.thresholdExceeded = thresholdExceeded;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public Instant getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(Instant timestamp) {
        this.timestamp = timestamp;
    }

    public boolean isForwardedToCloud() {
        return forwardedToCloud;
    }

    public void setForwardedToCloud(boolean forwardedToCloud) {
        this.forwardedToCloud = forwardedToCloud;
    }

    public boolean isAcknowledged() {
        return acknowledged;
    }

    public void setAcknowledged(boolean acknowledged) {
        this.acknowledged = acknowledged;
    }

    public Instant getAcknowledgedAt() {
        return acknowledgedAt;
    }

    public void setAcknowledgedAt(Instant acknowledgedAt) {
        this.acknowledgedAt = acknowledgedAt;
    }

    public String getAcknowledgedBy() {
        return acknowledgedBy;
    }

    public void setAcknowledgedBy(String acknowledgedBy) {
        this.acknowledgedBy = acknowledgedBy;
    }

    public String getAcknowledgementNotes() {
        return acknowledgementNotes;
    }

    public void setAcknowledgementNotes(String acknowledgementNotes) {
        this.acknowledgementNotes = acknowledgementNotes;
    }

    public boolean isResolved() {
        return resolved;
    }

    public void setResolved(boolean resolved) {
        this.resolved = resolved;
    }

    public Instant getResolvedAt() {
        return resolvedAt;
    }

    public void setResolvedAt(Instant resolvedAt) {
        this.resolvedAt = resolvedAt;
    }

    public String getResolvedBy() {
        return resolvedBy;
    }

    public void setResolvedBy(String resolvedBy) {
        this.resolvedBy = resolvedBy;
    }

    public String getResolutionNotes() {
        return resolutionNotes;
    }

    public void setResolutionNotes(String resolutionNotes) {
        this.resolutionNotes = resolutionNotes;
    }

    public String getDemonstrationNotice() {
        return demonstrationNotice;
    }

    public void setDemonstrationNotice(String demonstrationNotice) {
        this.demonstrationNotice = demonstrationNotice;
    }
}
